  ('ql-descending-ladder', null, 'quality_long', 'Descending ladder', array['build', 'peak']::text[], 45, '[{"label":"Main","text":"Descending ladder: {leg:2000:threshold}, 1 km row, 50 m lunges @ {w:lunges}, 50 WB; rest 3 min; then {leg:1000:threshold}, 500 m row, 25 m lunges, 25 WB. Transition immediately."}]'::jsonb, '{"row":1500,"lunges":75,"wb":75}'::jsonb, 'Oct 24, descending ladder', 4),
  ('ql-wb-bike-ladder', null, 'quality_long', 'Bike and wall ball ladder', array['build']::text[], 40, '[{"label":"Main","text":"Ladder up: 10-20-30-40-50 WB @ {w:wb}, with 15 cal bike before each set. Then 3 min easy and 4 × 250 m ski @ 2k pace, 1 min rest."}]'::jsonb, '{"wb":150,"ski":1000}'::jsonb, 'Apr 18, bike and WB ladders', 5),
  ('ql-machine-tempo', null, 'quality_long', 'Run + machine tempo', array['build', 'peak']::text[], 50, '[{"label":"Main","text":"{n:4} × ({leg:1000:threshold} + 500 m row @ 2k pace + 8 s + 25 m sled push @ {w:push}), 2 min rest. Break the push only at 5–6 m."}]'::jsonb, '{"row":2000,"push":100}'::jsonb, 'Apr 11, Run + Machine Tempo', 6),
